  const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  })[character]);

  const galleryId = (countryId) => `${countryId}-commander-gallery`;
  const archiveLabel = (country) => `${country.name} Commanders &amp; Military Person`;
  const countryId = document.body.dataset.commanderCountry;
  if (!countryId) {
    const legacyDirectory = document.querySelector(".commander-directory");
    if (legacyDirectory) legacyDirectory.remove();
    return;
  }

  const selectedCountry = countries.find((country) => country.id === countryId);
  const archive = document.getElementById("commander-archive");
  if (!selectedCountry || !archive) {
    console.error(`Commander archive data or page container is missing for "${countryId}".`);
    return;
  }

